-- Quiz CRPE : questions à choix multiples par matière, avec la bonne réponse et une brève explication.
-- Lecture uniquement par le serveur (/api/quiz/...) : RLS activée, aucune politique pour les clients.
create table if not exists public.quiz_questions (
  id bigint generated always as identity primary key,
  matiere text not null check (matiere in ('francais','mathematiques','histoire_geographie','emc','sciences_technologie','arts','anglais')),
  ordre int not null default 0,
  question text not null,
  choix jsonb not null check (jsonb_typeof(choix) = 'array' and jsonb_array_length(choix) between 2 and 6),
  reponse text not null,
  explication text not null,
  actif boolean not null default true,
  created_at timestamptz not null default now(),
  constraint quiz_questions_reponse_dans_choix check (choix ? reponse)
);
create index if not exists quiz_questions_matiere_idx on public.quiz_questions (matiere) where actif;
alter table public.quiz_questions enable row level security;

